import{z as s,x as i,o as e,c as l,q as r,j as t,D as a,d as n,s as o,S as B}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"委员会与评审流程","description":"","frontmatter":{"title":"委员会与评审流程","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/rc2-committee-process.md","filePath":"quant/rc2-committee-process.md","lastUpdated":1791413859000}'),d={name:"quant/rc2-committee-process.md"};function h(p,E,c,C,m,D){const A=i("Mermaid");return e(),l("div",null,[E[2]||(E[2]=r('<h1 id="委员会与评审流程" tabindex="-1">委员会与评审流程 <a class="header-anchor" href="#委员会与评审流程" aria-label="Permalink to &quot;委员会与评审流程&quot;">​</a></h1><div class="epigraph"><p>委员会裁决的不是科学品味，是证据的完整性；它的产出是挂在判据上的决定记录，不是会议纪要。</p><footer>—— 据 Arnott, Harvey and Markowitz, A Backtesting Protocol in the Era of Machine Learning, Journal of Financial Data Science, 2019 与站内 ML 投研工作流的门口径整理</footer></div><p><a href="/quant/rc2-knowledge-base">上一课</a>让组织记得住。记得住不等于裁得动：把策略押上模拟与实盘的决策，要动真金和限额，不能靠两个人在走廊里点头。本课写委员会与评审流程——组织层最硬的一环：三个门、一条边界、一套程序要件。它是<a href="/quant/fml-research-workflow">ML 投研工作流</a>「门有交付物」一条的机制化，也是<a href="/quant/sl-versioning-approval">版本与审批</a>在研究侧的上游。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>没有委员会的团队，放行决策有三个默认值，全是坏的。<strong>判据让位于人情</strong>：判据没达标，但提案人资历深、时机急，「再等等看」成了默认——放弃线在提案时写过，没人在有权停止的时刻翻出来。<strong>试验在最后一刻才被审视</strong>：上实盘前没人问过 \\(N\\) 是多少，<a href="/quant/rc2-experiment-management">实验管理</a>记的台账从头到尾没人读。<strong>驳回不留痕</strong>：不同意的人私下嘀咕，会议纪要写「一致通过」，组织学不到判据的边界在哪里。缺口不是「开个会」，是一套把<strong>停止的权力从提案人手里独立出来</strong>的程序：什么时候必须停，由预注册的判据和一群没有利益冲突的人说了算。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="三个门" tabindex="-1">三个门 <a class="header-anchor" href="#三个门" aria-label="Permalink to &quot;三个门&quot;">​</a></h3><p><strong>提案评审</strong>：研究开始前，判据预注册——主指标与放弃线先于任何结果存在，写进<a href="/quant/rc2-research-docs">一页假设文档</a>；评的是问题与判据，不评结果。<strong>定案评审</strong>：上模拟或实盘前，只查证据完整性——\\(N\\) 完整、复现包盲跑通过、台账指纹与声称的实验一致、判据达标；<a href="/quant/fml-research-workflow">ML 投研工作流</a>的交付物清单（契约、台账、审计包）在此逐项点收。<strong>衰减复审</strong>：上线后按信号半衰期定期重开，问的是「判据今天还成立吗」，衰减证据从<a href="/quant/sl-knowledge-management">策略台账</a>来。</p>',8)),(e(),t(B,null,{default:a(()=>[o(A,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20G1%7B%22%E9%97%A8%E4%B8%80%EF%BC%9A%E6%8F%90%E6%A1%88%E8%AF%84%E5%AE%A1%22%7D%20--%3E%7C%E5%88%A4%E6%8D%AE%E9%A2%84%E6%B3%A8%E5%86%8C%7C%20RES%5B%22%E7%A0%94%E7%A9%B6%E6%89%A7%E8%A1%8C%22%5D%0A%20%20RES%20--%3E%20G2%7B%22%E9%97%A8%E4%BA%8C%EF%BC%9A%E5%AE%9A%E6%A1%88%E8%AF%84%E5%AE%A1%22%7D%0A%20%20G2%20--%3E%7CN%20%E5%AE%8C%E6%95%B4%20%E7%9B%B2%E8%B7%91%E9%80%9A%E8%BF%87%20%E5%88%A4%E6%8D%AE%E8%BE%BE%E6%A0%87%7C%20GO%5B%22%E6%94%BE%E8%A1%8C%EF%BC%9A%E6%A8%A1%E6%8B%9F%2F%E5%AE%9E%E7%9B%98%22%5D%0A%20%20G2%20--%3E%7C%E4%B8%8D%E8%BE%BE%7C%20REJ%5B%22%E9%A9%B3%E5%9B%9E%EF%BC%9A%E7%90%86%E7%94%B1%E8%90%BD%E5%88%A4%E6%8D%AE%E5%85%A5%E5%BA%93%22%5D%0A%20%20REJ%20--%3E%20KB%5B%22%E7%9F%A5%E8%AF%86%E5%BA%93%EF%BC%9A%E5%A4%B1%E8%B4%A5%E6%A8%A1%E5%BC%8F%E6%B2%89%E6%B7%80%22%5D%0A%20%20GO%20--%3E%20G3%7B%22%E9%97%A8%E4%B8%89%EF%BC%9A%E8%A1%B0%E5%87%8F%E5%A4%8D%E5%AE%A1%22%7D%0A%20%20G3%20--%3E%7C%E5%88%A4%E6%8D%AE%E4%BB%8D%E6%88%90%E7%AB%8B%7C%20GO%0A%20%20G3%20--%3E%7C%E5%A4%B1%E6%95%88%7C%20DECAY%5B%22%E8%A1%B0%E5%87%8F%E5%A4%84%E7%BD%AE%20%E8%BD%AC%E5%85%A5%E5%8F%B0%E8%B4%A6%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[n(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>程序要件有三，缺一则会议退化成仪式。<strong>回避</strong>：提案人不参加对自己提案的表决——放行与否直接关系他的考核，利益冲突不可自裁。<strong>前置送达</strong>：材料提前到达，会上只裁不介绍；临时抛材料换来的不是深思是同情分。<strong>决定落判据</strong>：通过、驳回、有条件通过，每条理由必须指向预注册判据的具体条款——「效果不好」不是数据，是<a href="/quant/research-postmortem">研究复盘</a>钉死的口径；驳回理由是知识库的正式进料（上一课的入库三标准在这里接上）。边界一条：委员会裁决证据完整性，不裁决科学品味——「这个想法不够聪明」不进议程，品味之争回到提案文档与文献。</p><p><span class="marginnote">术语翻译：「判据预注册」就是把「什么算成功、什么算放弃」在看到任何数据之前写成书面条款，像考试前公布的评分标准——考完之后谁也不能临时改分数线。放弃线尤其如此：它必须在你还想继续跑下去的时候就已经存在，否则永远轮不到被触发。</span></p>',3)),(e(),t(B,null,{default:a(()=>[o(A,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%8F%90%E6%A1%88%E8%BF%9B%E5%85%A5%E5%AE%9A%E6%A1%88%E8%AF%84%E5%AE%A1%22%5D%20--%3E%20B%7B%22%E6%8F%90%E6%A1%88%E4%BA%BA%E5%9C%A8%E5%9C%BA%EF%BC%9F%22%7D%0A%20%20B%20--%3E%7C%22%E6%98%AF%22%7C%20C%5B%22%E6%8F%90%E6%A1%88%E4%BA%BA%E5%9B%9E%E9%81%BF%E5%90%8E%E8%A1%A8%E5%86%B3%22%5D%0A%20%20B%20--%3E%7C%22%E5%90%A6%22%7C%20D%5B%22%E9%80%90%E6%9D%A1%E5%AF%B9%E7%85%A7%E9%A2%84%E6%B3%A8%E5%86%8C%E5%88%A4%E6%8D%AE%22%5D%0A%20%20C%20--%3E%20D%0A%20%20D%20--%3E%20E%7B%22%E6%9D%A1%E6%AC%BE%E5%85%A8%E9%83%A8%E8%BE%BE%E6%A0%87%EF%BC%9F%22%7D%0A%20%20E%20--%3E%7C%22%E6%98%AF%22%7C%20F%5B%22%E9%80%9A%E8%BF%87%EF%BC%9A%E8%AE%B0%E5%BD%95%E6%8C%87%E7%BA%B9%E4%B8%8E%E6%97%A5%E6%9C%9F%22%5D%0A%20%20E%20--%3E%7C%22%E9%83%A8%E5%88%86%22%7C%20G%5B%22%E6%9C%89%E6%9D%A1%E4%BB%B6%E9%80%9A%E8%BF%87%EF%BC%9A%E5%86%99%E6%98%8E%E8%A1%A5%E9%BD%90%E9%A1%B9%22%5D%0A%20%20E%20--%3E%7C%22%E5%90%A6%22%7C%20H%5B%22%E9%A9%B3%E5%9B%9E%EF%BC%9A%E7%90%86%E7%94%B1%E8%90%BD%E5%85%B7%E4%BD%93%E6%9D%A1%E6%AC%BE%22%5D%0A%20%20H%20--%3E%20I%5B%22%E9%A9%B3%E5%9B%9E%E7%90%86%E7%94%B1%E5%85%A5%E5%BA%93%20%E7%9F%A5%E8%AF%86%E5%BA%93%E8%BF%9B%E6%96%99%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[n(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=r('<p><span class="marginnote">数字实例：判据写「样本外夏普 \\gt 0.8，且有效样本数 \\(N \\ge 200\\)」。某实验夏普 1.1 但 \\(N=180\\)，结论只能是「有条件通过，补齐样本后复审」——而不是会上一句「感觉还行」。决定落判据的意思是：把 1.1 \\gt 0.8 成立、180 \\lt 200 不成立这样逐条对勾写进记录，三个月后任何人都能重查这场表决。</span></p><p><span class="marginnote">节奏口径：低频高质，双周或月度，法定人数固定；被驳回不丢人、不计考核减分——否则提案人会学会把坏消息留在门外，委员会就只剩听好消息的功能，比没有委员会更糟。</span></p><h3 id="为什么门能拦住" tabindex="-1">为什么门能拦住 <a class="header-anchor" href="#为什么门能拦住" aria-label="Permalink to &quot;为什么门能拦住&quot;">​</a></h3><p>门的本质是把「停止」从一个非对称博弈里解放出来：提案人喊停，成本全在自己（白干几个月）；别人喊停，成本在关系。委员会把喊停的成本摊给制度，判据预先注册又把「什么时候该停」从临场判断变成查表。回测协议要求试验可数、决策按时间记录——门的会议记录正是决策的时间戳：谁、凭哪条判据、放行或拦下哪个指纹的实验。三个月后复盘实盘事故，这条记录能回答「当时的决定基于什么」，而不是「当时大家都觉得行」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>委员会不产生科学：它拦不住一个想法平庸但判据诚实的研究被做出来，也不应该拦——很多好信号第一眼平庸。它不替代数据核查：证据完整性检查的是「材料齐不齐、指纹对不对」，材料里的每个数字仍然由台账与复现包保证真。它的速度是真实成本：门槛过高，研究会绕开委员会走影子流程（<a href="/quant/research-sim-prod">研究、模拟、实盘隔离</a>警告过的分叉）；所以门只设在押上资源的时刻，探索期完全不设，频率随组织规模调节。</p><p><span class="marginnote">直觉类比：三个门像机场安检，不是每条走廊都设卡，只在「要上飞机」的地方查——对应研究流程里「要押真金和限额」的时刻。探索期不设门，正如没人会在去机场的路上被拦下搜包：查得太早太勤，人就改走小路，影子流程比没有安检更危险。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>没有委员会的三个坏默认：判据让人情、台账没人读、驳回不留痕。</li><li>三个门：提案评审（判据预注册）、定案评审（证据完整性点收）、衰减复审（判据是否仍成立）。</li><li>程序三要件：提案人回避、材料前置送达、决定逐条落判据；驳回理由是知识库的进料。</li><li>委员会裁决证据完整性，不裁决品味；门的成本用「只设在押资源的时刻」控制。</li><li>出处：Arnott, Harvey and Markowitz, <em>JFDS</em>, 2019；站内<a href="/quant/fml-research-workflow">ML 投研工作流</a>、<a href="/quant/sl-versioning-approval">版本与审批</a>、<a href="/quant/research-sim-prod">研究、模拟、实盘隔离</a>各课。</li></ul>',9))])}const F=s(d,[["render",h]]);export{f as __pageData,F as default};
